# Generated by `shiny theme new` from shiny-forest.jpg
# Base scheme: Everforest Dark (Medium) — https://github.com/mbadolato/iTerm2-Color-Schemes (via Ghostty)
# Edit freely; `shiny theme set <name>` re-applies.
THEME_BASE="Everforest Dark (Medium)"
GHOSTTY_THEME="Everforest Dark Med"   # built-in: ghostty +list-themes
ACCENT_PRESET=3                    # macOS accent: -1 graphite 0 red 1 orange 2 yellow 3 green 4 blue 5 purple 6 pink
WALLPAPER="wallpaper.jpg"

BG="#232A2E"         # window background
BG_DARK="#1D2226"    # frames, omnibox
SURFACE="#343F44"    # borders, dividers, inactive window border
SELECTION="#384B44"  # selected rows, text selection
MUTED="#475258"      # shortcuts, scrollbar
COMMENT="#7A8478"    # subtext, inactive tabs
FG="#D3C6AA"         # primary text
FG_DIM="#9DA9A0"     # secondary text
ACCENT="#83C092"     # primary accent: focus border, icons, links, text highlight, icon tint
ACCENT2="#7FBBB3"    # secondary accent: cursor, shortcuts, search selection
